	.macro formatwarp map:req, a, b, c
	map \map
	.ifb \a                                                      
		.byte WARP_ID_NONE
		.2byte -1    
		.2byte -1    
	.else
	.ifb \b                                                                         
		.byte \a           
		.2byte -1     
		.2byte -1     
	.else
	.ifb \c                                                                                
		.byte WARP_ID_NONE
		.2byte \a     
		.2byte \b     
	.else                                                                                    
		.byte \a          
		.2byte \b    
		.2byte \c    
	.endif
	.endif
	.endif
	.endm


	                                        
	                                                                                                 
	                                                                        
