	.byte 0

MauvilleCity_Mart_EventScript_Clerk: ; .global MauvilleCity_Mart_EventScript_Clerk
	lock
	faceplayer
	message gText_HowMayIServeYou
	waitmessage
	pokemart MauvilleCity_Mart_Pokemart
	msgbox gText_PleaseComeAgain, MSGBOX_DEFAULT
	release
	end

	.align 2
