	.byte 0xBE, 0xE3, 0xE2, 0xB4, 0xE8, 0x00, 0xE8, 0xDC, 0xD9, 0xED, 0x00, 0xDC, 0xD5, 0xEA, 0xD9, 0x00, 0xE7, 0xD9, 0xE8, 0x00, 0xD8, 0xD5, 0xE8, 0xD9, 0xE7, 0x00, 0xDA, 0xE3, 0xE6, 0x00, 0xE8, 0xDC, 0xD9, 0xDD, 0xE6, 0xFE
