	.byte 0xC3, 0x00, 0xEB, 0xD5, 0xE8, 0xD7, 0xDC, 0x00, 0xCE, 0xD0, 0xB8, 0x00, 0xD6, 0xE9, 0xE8, 0x00, 0xE8, 0xDC, 0xD9, 0xED, 0x00, 0xE2, 0xD9, 0xEA, 0xD9, 0xE6, 0x00, 0xE7, 0xDC, 0xE3, 0xEB, 0x00, 0xD5, 0xE2, 0xED, 0xFE
