	frontier_set FRONTIER_DATA_HEARD_BRAIN_SPEECH
BattleFrontier_BattleTowerBattleRoom_EventScript_BattleAnabelGold: ; .global BattleFrontier_BattleTowerBattleRoom_EventScript_BattleAnabelGold
