BattleFrontier_BattleFactoryLobby_EventScript_RulesBoard: ; .global BattleFrontier_BattleFactoryLobby_EventScript_RulesBoard
	lockall
	msgbox BattleFrontier_BattleFactoryLobby_Text_RulesAreListed, MSGBOX_DEFAULT
