	waitstate
	release
	end

FarawayIsland_Entrance_EventScript_AsYouLike: ; .global FarawayIsland_Entrance_EventScript_AsYouLike
	msgbox EventTicket_Text_AsYouLike, MSGBOX_DEFAULT
