	special CloseDeptStoreElevatorWindow
	releaseall
	end

TrainerHill_Elevator_EventScript_MoveElevator: ; .global TrainerHill_Elevator_EventScript_MoveElevator
	waitse
	special MoveElevator
	waitstate
	return

