	.byte 0xBB, 0xD5, 0xDF, 0xAB, 0xFE
	.byte 0xD3, 0xE3, 0xE9, 0xB4, 0xEA, 0xD9, 0x00, 0xE1, 0xD5, 0xD8, 0xD9, 0x00, 0xDD, 0xE8, 0x00, 0xE8, 0xE3, 0x00, 0xE1, 0xD9, 0xAC, 0xFA
